#!/bin/bash
set -e
# 先解析脚本自身绝对路径（必须在 cd avbox 之前，否则 dirname 的相对路径会错）
SCRIPT_ABS="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"
export SCRIPT_ABS
cd avbox
echo "=== 播放器 Spotify 风格重写 ==="
PKG_DIR="app/src/main/java/com/github/tvbox/osc/ui/activity"
echo ""
echo ""

# 解码写入播放器文件（blob0=LxPlayerActivity.kt, blob1=LxPlayerManager.kt）
# （SCRIPT_ABS 已在脚本开头解析，此处不再重复）
python3 << PYEOF_DECODE
import re, base64, gzip, os
with open(os.environ.get("SCRIPT_ABS", "13_music_player.sh"), encoding="utf-8") as f:
    c = f.read()
blobs = re.findall(r'echo "(H4s[A-Za-z0-9+/=\n]+)"', c)
names = ["LxPlayerActivity.kt", "LxPlayerManager.kt"]
pkg = "app/src/main/java/com/github/tvbox/osc/ui/activity"
for blob, name in zip(blobs, names):
    data = gzip.decompress(base64.b64decode(blob.replace("\n", "")))
    open(os.path.join(pkg, name), "wb").write(data)
    print(name, "已写入", len(data), "字节")
PYEOF_DECODE
echo "LxPlayerManager.kt 已更新"

# 注册 LxPlayerActivity / Receiver / Service 到 AndroidManifest.xml
MANIFEST="app/src/main/AndroidManifest.xml"
if ! grep -q "LxPlayerActivity" "$MANIFEST"; then
    python3 << 'PYEOF2'
mf = "app/src/main/AndroidManifest.xml"
c = open(mf, encoding='utf-8').read()
for act in [".ui.activity.LxPlayerActivity", ".ui.activity.LxHistoryActivity"]:
    if act not in c:
        c = c.replace('</application>', '        <activity android:name="%s" android:exported="false" />\n    </application>' % act, 1)
        print(act, "已注册")
rt = '<receiver android:name=".ui.activity.LxNotificationReceiver"'
if rt not in c:
    c = c.replace('</application>', '        ' + rt + ' android:exported="false">\n            <intent-filter>\n                <action android:name="com.github.tvbox.osc.lx.ACTION_TOGGLE" />\n                <action android:name="com.github.tvbox.osc.lx.ACTION_NEXT" />\n                <action android:name="com.github.tvbox.osc.lx.ACTION_PREV" />\n                <action android:name="com.github.tvbox.osc.lx.ACTION_CLOSE" />\n            </intent-filter>\n        </receiver>\n    </application>', 1)
    print("LxNotificationReceiver 已注册")
st = '<service android:name=".ui.activity.LxMusicService"'
if st not in c:
    c = c.replace('</application>', '        ' + st + ' android:exported="false" android:foregroundServiceType="mediaPlayback" />\n    </application>', 1)
    print("LxMusicService 已注册")
for p in ["android.permission.FOREGROUND_SERVICE", "android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK"]:
    if p not in c:
        tag = '<uses-permission android:name="%s" />\n    ' % p
        c = c.replace('<application', tag + '<application', 1)
        print(p, "已添加")
open(mf, 'w', encoding='utf-8').write(c)
PYEOF2
fi


echo "=== 播放器 Spotify 风格完成 ==="
